        public static async Task<List<SendFileToTarasolReturnedData>> SendFilesStreamToTarasolAsync(IFormFileCollection Files, string InterfaceID)
        {
            try
            {
                List<SendFileToTarasolReturnedData> SenFileToTarasolReurnedDataList = new List<SendFileToTarasolReturnedData>();
                //Get Interface object from cache
                object Interface = Cache.GetFromCache(InterfaceID);
                if (Interface == null)
                {
                    Exception ex = new Exception();
                    Exception e2 = (Exception)Activator.CreateInstance(ex.GetType(), "Invalid Trasol User session", ex);
                    throw e2;
                }
                DownloadUploadRequest downloadUploadRequest = JsonConvert.DeserializeObject<DownloadUploadRequest>(Interface.ToString());
                Logger.AddToLogFile(System.Reflection.MethodBase.GetCurrentMethod().Name, Logger.Enum_LogType._Info, "PageGUID : " + downloadUploadRequest.PageGUID);

                foreach (var file in Files)
                {
                    string name = ContentDispositionHeaderValue.Parse(file.ContentDisposition).FileName.Trim('"');
                    //Service only works with zip files
                    if (file.Length > 0 && name.EndsWith(".zip"))
                    {
                        string tempGuid = Guid.NewGuid().ToString();
                        try
                        {
                            MemoryStream memoryStream = new MemoryStream();
                            file.CopyTo(memoryStream);
                            byte[] FileBytes;
                            using (var br = new BinaryReader(file.OpenReadStream()))
                            {
                                FileBytes = br.ReadBytes((int)(file.OpenReadStream().Length));
                            }
                            Directory.CreateDirectory(Cache.GetFromCache("DataFolder") + @"\" + tempGuid);
                            string tempPath = Cache.GetFromCache("DataFolder") + @"\" + tempGuid + @"\" + name;
                            File.WriteAllBytes(tempPath, FileBytes);
                            ZipFile.ExtractToDirectory(tempPath, tempPath.Replace(name, ""));
                            string[] subFiles = Directory.GetFiles(tempPath.Replace(name, ""));
                            Logger.AddToLogFile(System.Reflection.MethodBase.GetCurrentMethod().Name, Logger.Enum_LogType._Info, "fILE cOUNT: " + subFiles.Count());

                            if (subFiles.Length > 0)
                            {
                                foreach (var filePath in subFiles)
                                {
                                    //Call "scan file upload" from tarasol for each file
                                    if (!Path.GetFileName(filePath).EndsWith(name))
                                    {
                                        try
                                        {
                                            Logger.AddToLogFile(System.Reflection.MethodBase.GetCurrentMethod().Name, Logger.Enum_LogType._Info, "fILE name: " + Path.GetFileName(filePath));
                                            string RequestURL = Cache.GetFromCache("APIURL") + "/Corr/ScanFileUpload?" + "PageGUID=" + downloadUploadRequest.PageGUID
                                                + "&OrignalFileName=" + Path.GetFileName(filePath);
                                            Logger.AddToLogFile(System.Reflection.MethodBase.GetCurrentMethod().Name, Logger.Enum_LogType._Info, "Request URL: " + RequestURL);
                                            byte[] fileBytes = File.ReadAllBytes(filePath);
                                            SendFileToTarasolReturnedData senFileToTarasolReurnedData = await CallExternalAPI.CallPostFileAPIAsync(fileBytes, Path.GetFileName(filePath), RequestURL, "");
                                            SenFileToTarasolReurnedDataList.Add(senFileToTarasolReurnedData);
                                        }
                                        catch (Exception ex)
                                        {
                                            Directory.Delete(Cache.GetFromCache("DataFolder") + @"\" + tempGuid, true);
                                            Logger.AddToLogFile(System.Reflection.MethodBase.GetCurrentMethod().Name, Logger.Enum_LogType._Error, "ex.Message : " + ex.Message);
                                            break;
                                            throw ex;
                                        }
                                    }
                                }
                            }
                            Directory.Delete(Cache.GetFromCache("DataFolder") + @"\" + tempGuid, true);
                        }
                        catch (Exception)
                        {
                            Directory.Delete(Cache.GetFromCache("DataFolder") + @"\" + tempGuid, true);
                            throw;
                        }

                    }

                }
                return SenFileToTarasolReurnedDataList;
            }
            catch (Exception ex)
            {
                throw ex;
            }

            //Return File Stream
        }


