        public static async Task<IntResult> SendFilesToTarasolAsync(List<Attachment> attachments, string InterfaceID)
        {
            try
            {
                //Dummy For Test
                IntResult jsonResult = IntResultLib.GetResult(2);
                //if(attachments.Count > 0)
                //{
                //    jsonResult = IntResultLib.GetResult(1);
                //}
                //else
                //{
                //    jsonResult = IntResultLib.GetResult(2);
                //}
                object Interface = Cache.GetFromCache(InterfaceID);
                if (Interface == null)
                {
                    Exception ex = new Exception();
                    Exception e2 = (Exception)Activator.CreateInstance(ex.GetType(), "Invalid Trasol User session", ex);
                    throw e2;
                }
                DownloadUploadRequest downloadUploadRequest = JsonConvert.DeserializeObject<DownloadUploadRequest>(Interface.ToString());
                Logger.AddToLogFile(System.Reflection.MethodBase.GetCurrentMethod().Name, Logger.Enum_LogType._Info, " DocUID : " + downloadUploadRequest.DocUID);

                foreach (var attachment in attachments)
                {
                    if (attachment.FileContent.Length > 0)
                    {
                        Logger.AddToLogFile(System.Reflection.MethodBase.GetCurrentMethod().Name, Logger.Enum_LogType._Info, " ScanFileUpload: " + attachment.FileName);
                        string RequestURL = Cache.GetFromCache("APIURL") + "/Corr/ScanFileUpload?" + "PageGUID=" + downloadUploadRequest.DocUID + "&OrignalFileName=" + attachment.FileName;
                        jsonResult = await CallExternalAPI.CallPostFileAPIAsync(attachment.FileContent, attachment.FileName, RequestURL, "");
                    }
                    jsonResult = IntResultLib.GetResult(1);
                }
                return jsonResult;
            }
            catch (Exception ex)
            {
                return IntResultLib.GetResult(ex);
            }

            //Return File Stream
        }
    }
